"""Coordinator holding the latest openGym events for sensors."""

from __future__ import annotations

from typing import Any, Callable

from homeassistant.core import HomeAssistant, callback

from .const import EVENT_TYPES


class OpenGymCoordinator:
    """Track the most recent event of each openGym event type."""

    def __init__(self, hass: HomeAssistant) -> None:
        self.hass = hass
        self.listeners: set[Callable[[], None]] = set()
        # event_type -> last event dict
        self.last: dict[str, dict[str, Any]] = {}

    def update(self, event_type: str, event: dict[str, Any]) -> None:
        """Remember the newest event of its kind."""
        self.last[event_type] = event

    @callback
    def async_get_last(self, event_type: str) -> dict[str, Any] | None:
        """Return the last event of a type, or None."""
        return self.last.get(event_type)

    @callback
    def async_listen(self, listener: Callable[[], None]) -> Callable[[], None]:
        """Register a listener notified when any event arrives."""
        self.listeners.add(listener)

        @callback
        def _remove() -> None:
            self.listeners.discard(listener)

        return _remove

"""Config flow for the openGym integration."""

from __future__ import annotations

import secrets
from typing import Any

import voluptuous as vol

from homeassistant.config_entries import ConfigFlow, ConfigFlowResult
from homeassistant.helpers import config_validation as cv

from .const import CONF_NAME, CONF_SECRET, CONF_WEBHOOK_ID, DOMAIN


class OpenGymConfigFlow(ConfigFlow, domain=DOMAIN):
    """Handle a config flow for openGym."""

    VERSION = 1

    async def async_step_user(
        self, user_input: dict[str, Any] | None = None
    ) -> ConfigFlowResult:
        """Ask for the signing secret and create the entry."""
        errors: dict[str, str] = {}
        if user_input is not None:
            secret = user_input.get(CONF_SECRET, "").strip()
            if secret and not all(c in "0123456789abcdefABCDEF" for c in secret):
                errors["base"] = "invalid_secret"
            else:
                await self.async_set_unique_id(secrets.token_hex(8))
                self._abort_if_unique_id_configured()
                return self.async_create_entry(
                    title=user_input.get(CONF_NAME) or "openGym",
                    data={
                        CONF_WEBHOOK_ID: f"{DOMAIN}_{secrets.token_hex(8)}",
                        CONF_SECRET: secret,
                    },
                )

        return self.async_show_form(
            step_id="user",
            data_schema=vol.Schema(
                {
                    vol.Required(CONF_NAME, default="openGym"): cv.string,
                    vol.Optional(CONF_SECRET, default=""): cv.string,
                }
            ),
            errors=errors,
        )

